package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Integer;
    attribute accumulatedMs : Integer := 0;
    attribute ledState : Boolean := false;
    attribute serialSent : Boolean := false;
    perform action tick {
      first start;
      then assign accumulatedMs := accumulatedMs + io_1;
      then if ((((accumulatedMs) >= (1000))) and (true)) {
        first start;
        then assign accumulatedMs := accumulatedMs - 1000;
        then assign ledState := not ledState;
      }
      then if ((not serialSent) and (((accumulatedMs) == (0)))) {
        first start;
        then assign serialSent := true;
      }
    }
    out attribute io_0 : Boolean = ledState;
    out attribute io_2 : Boolean = (if not serialSent ? true else false);
  }
  part system : Controller;
}
